// generated by plugin/scripts/build.mjs from cli/src (piezas 0.7.4); do not edit by hand
// Part of the piezas CLI (see index.js).
//
// ===========================================================================
// The guard on the project's own hooks: what keeps the guardrails in place
// ===========================================================================
//
// `piezas init` installs the Piezas checks as the project's own hooks
// (projecthooks.js). The AI must not be able to switch them off. What counts
// as touching them:
//   - the hook file, the CLI it loads and the rules it reads:
//     .piezas/hooks/**, node_modules/piezas/**, .piezas/rules/**, npm's record
//     of what is installed (node_modules/.package-lock.json) and pnpm's copy;
//   - the settings that run them: .claude/settings.json, .claude/settings.local.json,
//     .codex/hooks.json, .codex/config.toml. A change through the edit tools is
//     judged by the file it would leave: only the keys an app may change
//     (APP_SETTINGS_KEYS) may differ; hooks, permissions, env, statusLine,
//     helpers and every other key stay as they are; Codex hooks are not turned
//     off (a small TOML reading: tables, dotted and quoted keys, inline tables).
//     A shell change to them cannot be read in advance: refused;
//   - the lock files' piezas entry, the .npmrc settings that decide what gets
//     installed, and package.json's piezas entry;
//   - a delete or move of a folder that holds them (.claude, .codex, .piezas,
//     node_modules, the project folder itself);
//   - git, tar, unzip and patch commands that put back, unpack or apply files
//     there; installing from a folder, file or tarball; installing without the
//     dev tools (--omit=dev, --production, prune); package-manager commands
//     run through corepack, npx, npm exec or dlx; deleters (rimraf); find -delete;
//   - inline scripts that write and name any of this (even split in two).
// The owner can always do any of this in their own terminal, or let the AI
// for one session with their own "allow outside changes".
//
// Known limit (a text guard): code piped in on stdin, a script written to a
// file and then run, and `npm run` wrappers are not seen inside.
//
// Paths are compared case-insensitively where the file system ignores case
// (macOS, Windows), after resolving symbolic links in the folders above.
import { spawnSync } from 'child_process';
import { existsSync, readFileSync } from 'fs';
import { basename, dirname, isAbsolute, join, relative, resolve, sep } from 'path';
import { PROJECT_HOOK_MARKER } from './constants.js';
// Functions only, used at call time: the import cycles with these are safe.
import { hookStateDir } from './hookentry.js';
import { expectedHookEntries } from './projecthooks.js';
import { realish, tokenizeShell, expandWord } from './workspace.js';

export const HOOK_SETTINGS_FILES = ['.claude/settings.json', '.claude/settings.local.json', '.codex/hooks.json'];
export const CODEX_CONFIG_FILE = '.codex/config.toml';
export const PROTECTED_FILES = [...HOOK_SETTINGS_FILES, CODEX_CONFIG_FILE];
export const PROTECTED_TREES = ['.piezas/hooks', '.piezas/rules', 'node_modules/piezas', 'node_modules/.package-lock.json'];
export const LOCK_FILES = ['package-lock.json', 'npm-shrinkwrap.json', 'pnpm-lock.yaml', 'yarn.lock', 'bun.lock'];
// Folders whose delete or replacement takes protected files with it.
export const PROTECTED_HOLDERS = ['.claude', '.codex', '.piezas', 'node_modules'];
// Names a protected path can have, for patterns (find -name, cp x/* ...).
const PROTECTED_NAMES = ['settings.json', 'settings.local.json', 'hooks.json', 'config.toml', 'hook.mjs', 'hookentry.js', 'piezas', 'hooks', 'rules', '.claude', '.codex', '.piezas', 'node_modules', '.package-lock.json'];
// The keys of a Claude Code settings file an app may change: none of them can
// run a command, change what is allowed, or switch hooks off.
export const APP_SETTINGS_KEYS = new Set(['$schema', 'model', 'includeCoAuthoredBy', 'cleanupPeriodDays', 'outputStyle', 'alwaysThinkingEnabled', 'spinnerTipsEnabled', 'theme', 'language']);
// Environment settings that reach every hook's node (kept for messages).
export const RISKY_ENV = /^(?:NODE_[A-Z0-9_]*|LD_[A-Z0-9_]*|DYLD_[A-Z0-9_]*|PATH|PIEZAS_[A-Z0-9_]*|CLAUDE_PROJECT_DIR|BASH_ENV|ENV|ZDOTDIR|SHELL|HOME|TMPDIR)$/i;

export function caseInsensitiveFs(env = process.env) {
  if (env.PIEZAS_FS_CASE === 'sensitive') return false;
  if (env.PIEZAS_FS_CASE === 'insensitive') return true;
  return process.platform === 'darwin' || process.platform === 'win32';
}

export function foldPath(p, env = process.env) {
  return caseInsensitiveFs(env) ? String(p).toLowerCase() : String(p);
}

// relKey — abs as a project-relative posix path, case-folded where the file
// system ignores case; null when it is outside the project.
export function relKey(abs, project, env = process.env) {
  const rel = relative(foldPath(realish(project), env), foldPath(realish(abs), env)).split(sep).join('/');
  if (rel.startsWith('..') || isAbsolute(rel)) return null;
  return rel;
}

// samePath — the same file, as the file system sees it.
export function samePath(a, b, env = process.env) {
  return foldPath(realish(a), env) === foldPath(realish(b), env);
}

// inHookStateDir — the private folder where the hook entries keep their marks.
export function inHookStateDir(abs, env = process.env) {
  const dir = foldPath(realish(hookStateDir(env)), env);
  const rel = relative(dir, foldPath(realish(abs), env));
  return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel));
}

function readText(abs) {
  try { return readFileSync(abs, 'utf-8'); } catch { return ''; }
}

// hooksInstalled — the project runs its own Piezas hooks: its settings hold
// the Piezas entries (or the hook file is there). Not the hook file alone: a
// deleted hook file must not switch the guard off.
export function hooksInstalled(project) {
  if (existsSync(join(project, PROJECT_HOOK_MARKER))) return true;
  return ['.claude/settings.json', '.codex/hooks.json'].some((rel) => holdsPiezasEntries(rel, readText(join(project, rel))));
}

// protectedKind — 'tree' | 'settings' | 'config' | 'holder' | 'package' |
// 'lock' | 'npmrc' | null.
export function protectedKind(rel) {
  if (rel === null || rel === undefined) return null;
  if (PROTECTED_TREES.some((t) => rel === t || rel.startsWith(`${t}/`))) return 'tree';
  if (/^node_modules\/\.pnpm\/piezas@/.test(rel)) return 'tree';
  if (HOOK_SETTINGS_FILES.includes(rel)) return 'settings';
  if (rel === CODEX_CONFIG_FILE) return 'config';
  if (rel === '' || PROTECTED_HOLDERS.includes(rel)) return 'holder';
  if (rel === 'package.json') return 'package';
  if (LOCK_FILES.includes(rel)) return 'lock';
  if (rel === '.npmrc') return 'npmrc';
  return null;
}

function stripBom(text) {
  return typeof text === 'string' ? text.replace(/^﻿/, '') : text;
}

function parseJson(text) {
  try {
    const v = JSON.parse(stripBom(text));
    return v && typeof v === 'object' && !Array.isArray(v) ? v : null;
  } catch {
    return null;
  }
}

// entryPresent — the settings hold the Piezas entry for this event exactly:
// a group with the expected matcher whose hooks include the expected command.
export function entryPresent(settings, event, expected) {
  const groups = settings?.hooks?.[event];
  if (!Array.isArray(groups)) return false;
  return groups.some((g) => g && typeof g === 'object' && (g.matcher ?? '') === (expected.matcher ?? '') &&
    Array.isArray(g.hooks) && g.hooks.some((h) => h && h.type === 'command' && h.command === expected.command));
}

// holdsPiezasEntries — does this settings text run the Piezas hook file?
export function holdsPiezasEntries(rel, text) {
  if (typeof text !== 'string' || !text) return false;
  const parsed = parseJson(text);
  if (parsed) {
    const expected = expectedHookEntries(rel === '.codex/hooks.json' ? 'codex' : 'claude');
    if (Object.entries(expected).some(([event, entry]) => entryPresent(parsed, event, entry))) return true;
  }
  return text.includes(PROJECT_HOOK_MARKER) || text.includes("'.piezas','hooks','hook.mjs'");
}

// settingsContentProblem — why the file `rel` with this new text would change
// the guardrails (or what runs beside them), or null. Only APP_SETTINGS_KEYS
// may differ from the file as it is now; .codex/hooks.json has none.
export function settingsContentProblem(rel, current, proposed) {
  if (typeof proposed !== 'string') return `${rel} runs the Piezas guardrails, and this change could not be checked`;
  const next = parseJson(proposed);
  if (!next) return `${rel} runs the Piezas guardrails, and this would leave it unreadable (not valid JSON)`;
  if (next.disableAllHooks) return `${rel} would switch off every hook ("disableAllHooks"), the Piezas guardrails included`;
  const now = parseJson(current) ?? {};
  const allowed = rel === '.codex/hooks.json' ? new Set(['$schema']) : APP_SETTINGS_KEYS;
  for (const key of new Set([...Object.keys(now), ...Object.keys(next)])) {
    if (allowed.has(key) || JSON.stringify(now[key]) === JSON.stringify(next[key])) continue;
    if (key === 'env') {
      const risky = Object.keys(next.env ?? {}).find((k) => RISKY_ENV.test(k));
      if (risky) return `${rel} would set ${risky} for every hook, which can change or stop the Piezas guardrails`;
    }
    if (key === 'hooks') return `${rel} runs the Piezas guardrails, and this would change its hooks (the Piezas entries or what runs beside them)`;
    return `${rel} runs the Piezas guardrails, and this would change its "${key}" setting, which an app may not change`;
  }
  return null;
}

// --- .codex/config.toml: a small TOML reading -----------------------------------

function tomlKeyParts(text) {
  const parts = [];
  let cur = '';
  let quote = null;
  for (const c of String(text)) {
    if (quote) { if (c === quote) quote = null; else cur += c; continue; }
    if (c === '"' || c === "'") { quote = c; continue; }
    if (c === '.') { parts.push(cur.trim()); cur = ''; continue; }
    cur += c;
  }
  parts.push(cur.trim());
  return parts.filter((p) => p !== '');
}

function stripTomlComment(line) {
  let quote = null;
  for (let i = 0; i < line.length; i += 1) {
    const c = line[i];
    if (quote) { if (c === quote) quote = null; continue; }
    if (c === '"' || c === "'") { quote = c; continue; }
    if (c === '#') return line.slice(0, i);
  }
  return line;
}

// tomlValues — every key path the text sets (table.key, dotted, quoted, inline
// tables), with its value as written (whitespace-trimmed).
export function tomlValues(text) {
  const out = new Map();
  let table = [];
  const setPair = (prefix, left, right) => {
    const path = [...prefix, ...tomlKeyParts(left)];
    const value = right.trim();
    if (value.startsWith('{') && value.endsWith('}')) {
      for (const pair of value.slice(1, -1).split(',')) {
        const eq = pair.indexOf('=');
        if (eq > 0) setPair(path, pair.slice(0, eq), pair.slice(eq + 1));
      }
      return;
    }
    out.set(path.join('.'), value.replace(/^(['"])(.*)\1$/, '$2').toLowerCase());
  };
  for (const raw of String(text || '').split(/\r?\n/)) {
    const line = stripTomlComment(raw).trim();
    if (!line) continue;
    const header = /^\[\[?\s*(.+?)\s*\]\]?$/.exec(line);
    if (header) { table = tomlKeyParts(header[1]); continue; }
    const eq = line.indexOf('=');
    if (eq > 0) setPair(table, line.slice(0, eq), line.slice(eq + 1));
  }
  return out;
}

const hookKeys = (values) => [...values.keys()].filter((k) => /(?:^|\.)(?:codex_)?hooks$/.test(k));

export function codexConfigProblem(current, proposed) {
  if (typeof proposed !== 'string') return `${CODEX_CONFIG_FILE} decides whether Codex runs the Piezas guardrails, and this change could not be checked`;
  const now = tomlValues(current);
  const next = tomlValues(proposed);
  for (const key of new Set([...hookKeys(now), ...hookKeys(next)])) {
    // Any change of a hooks key, except switching it on.
    if (now.get(key) !== next.get(key) && next.get(key) !== 'true') return `${CODEX_CONFIG_FILE} would change whether Codex runs hooks (${key}), the Piezas guardrails included`;
  }
  return null;
}

// --- package.json, lock files, .npmrc ---------------------------------------------

const DEP_FIELDS = ['dependencies', 'devDependencies', 'optionalDependencies', 'peerDependencies'];
function piezasSpecs(pkg) {
  const out = {};
  for (const f of DEP_FIELDS) if (pkg?.[f] && typeof pkg[f] === 'object' && typeof pkg[f].piezas === 'string') out[f] = pkg[f].piezas;
  for (const f of ['overrides', 'resolutions', 'pnpm']) {
    const v = f === 'pnpm' ? pkg?.pnpm?.overrides : pkg?.[f];
    if (v && typeof v === 'object') for (const [k, s] of Object.entries(v)) if (/(^|[/>])piezas(@|$)/.test(k)) out[`${f}:${k}`] = JSON.stringify(s);
  }
  if (pkg?.name === 'piezas') out.name = 'piezas';
  return out;
}

// packageJsonProblem — a package.json change that drops or re-pins the piezas
// tools the hooks run (or names the project itself "piezas"), or null.
export function packageJsonProblem(current, proposed) {
  const now = parseJson(current);
  if (!now) return null; // no readable package.json today: nothing to keep
  const before = piezasSpecs(now);
  if (!Object.keys(before).length && now.name !== 'piezas') {
    if (typeof proposed !== 'string') return null;
    const next = parseJson(proposed);
    if (!next) return null;
    const after = piezasSpecs(next);
    return Object.keys(after).length ? 'package.json would change the piezas tools the guardrails run' : null;
  }
  if (typeof proposed !== 'string') return 'package.json declares the piezas tools the guardrails run, and this change could not be checked';
  const next = parseJson(proposed);
  if (!next) return 'package.json declares the piezas tools the guardrails run, and this would leave it unreadable';
  return JSON.stringify(piezasSpecs(next)) === JSON.stringify(before) ? null : 'package.json would change or drop the piezas tools the guardrails run';
}

// lockPiezasEntry — what a lock file says about piezas (JSON locks: the entry;
// text locks: the lines of its block).
export function lockPiezasEntry(rel, text) {
  if (rel.endsWith('.json')) {
    const lock = parseJson(text);
    if (!lock) return text && /piezas/.test(text) ? `unreadable:${text.length}` : null;
    const entry = lock.packages?.['node_modules/piezas'] ?? lock.dependencies?.piezas ?? null;
    return entry ? JSON.stringify(entry) : null;
  }
  const lines = String(text || '').split(/\r?\n/);
  const picked = [];
  lines.forEach((line, i) => {
    if (/(?:^|[\s'"/])piezas[@:]/.test(line)) picked.push(...lines.slice(i, i + 6));
  });
  return picked.length ? picked.join('\n') : null;
}

const NPMRC_KEYS = /^\s*(?:omit|production|only|include|also|registry|@[^:]+:registry|link|install-links|ignore-scripts|global|prefix|lockfile-version|package-lock|save)\s*=/im;

// fileProblem — the hooks guard for one target (edit tools: how = 'write' |
// 'delete'; shell: 'shell-write' | 'shell-delete'). proposed is the whole new
// text for an edit-tool write (null when it could not be worked out).
export function fileProblem(abs, project, how, proposed, env = process.env) {
  if (!project) return null;
  const rel = relKey(abs, project, env);
  const kind = protectedKind(rel);
  if (!kind) {
    // A pattern in a protected folder (cp x/* .claude/, rm .codex/*).
    const name = basename(abs);
    if (rel && /[*?[\]{]/.test(name) && hooksInstalled(project)) {
      const parentRel = rel.slice(0, Math.max(0, rel.length - name.length - 1));
      const re = globToRegExp(foldPath(name, env));
      if ((parentRel === '' || PROTECTED_HOLDERS.includes(parentRel) || PROTECTED_TREES.includes(parentRel) || PROTECTED_TREES.some((t) => t.startsWith(`${parentRel}/`)))
        && PROTECTED_NAMES.some((n) => re.test(n))) {
        return `the pattern ${rel} could reach the files that run the Piezas guardrails`;
      }
    }
    return null;
  }
  const deleting = how === 'delete' || how === 'shell-delete';
  const shell = how === 'shell-write' || how === 'shell-delete';
  if (kind === 'tree') return `${rel} is part of the Piezas guardrails (the checks, the tools they run, or the rules they read)`;
  const installed = hooksInstalled(project);
  if (kind === 'holder') {
    if (!installed && !(rel === 'node_modules' && existsSync(join(project, 'node_modules', 'piezas')))) return null;
    if (deleting) return `${rel || 'the project folder'} holds the files that run the Piezas guardrails, and this would delete or move it`;
    if (rel !== '') return `${rel} holds the files that run the Piezas guardrails, and this would replace it`;
    return null;
  }
  if (!installed) return null;
  const current = readText(abs);
  if (kind === 'package') {
    if (deleting) return 'package.json declares the piezas tools the guardrails run, and this would delete it';
    if (shell) return packageJsonProblem(current, null);
    return packageJsonProblem(current, proposed);
  }
  if (kind === 'lock') {
    if (deleting) return null; // a fresh install takes piezas from npm again
    const before = lockPiezasEntry(rel, current);
    if (shell) return before ? `${rel} records where the piezas tools come from; change it with the edit tool` : null;
    if (typeof proposed !== 'string') return before ? `${rel} records where the piezas tools come from, and this change could not be checked` : null;
    return lockPiezasEntry(rel, proposed) === before ? null : `${rel} would change where the piezas tools the guardrails run come from`;
  }
  if (kind === 'npmrc') {
    if (deleting) return null;
    if (shell) return '.npmrc decides what npm installs; change it with the edit tool';
    if (typeof proposed !== 'string') return '.npmrc decides what npm installs, and this change could not be checked';
    const keys = (t) => String(t || '').split(/\r?\n/).filter((l) => NPMRC_KEYS.test(l)).map((l) => l.trim()).sort().join('\n');
    return keys(proposed) === keys(current) ? null : '.npmrc would change what npm installs (or from where), the piezas tools included';
  }
  if (kind === 'config') {
    const hooksSet = hookKeys(tomlValues(current)).length > 0;
    if (deleting) return hooksSet ? `${CODEX_CONFIG_FILE} decides whether Codex runs hooks, and this would delete it` : null;
    if (shell) return `${CODEX_CONFIG_FILE} decides whether Codex runs the Piezas guardrails; change it with the edit tool`;
    return codexConfigProblem(current, proposed);
  }
  // settings
  const hasEntries = holdsPiezasEntries(rel, current);
  if (deleting) return hasEntries ? `${rel} runs the Piezas guardrails, and this would delete it` : null;
  if (shell) return `${rel} holds the settings that run the Piezas guardrails; change it with the edit tool`;
  return settingsContentProblem(rel, current, proposed);
}

function globToRegExp(pattern) {
  let re = '';
  for (const c of pattern) {
    if (c === '*') re += '.*';
    else if (c === '?') re += '.';
    else if (c === '[' || c === ']') re += c;
    else re += c.replace(/[.+^${}()|\\]/g, '\\$&');
  }
  try { return new RegExp(`^${re}$`); } catch { return /^.*$/; }
}

// --- shell commands -----------------------------------------------------------

const MENTIONS = /settings\.json|settings\.local\.json|hooks\.json|config\.toml|hook\.mjs|hookentry|\.claude|\.codex|node_modules|\.piezas|package\.json|package-lock|\.npmrc|piezas-hooks/i;
const PM = new Set(['npm', 'pnpm', 'yarn', 'bun']);
const PM_CHANGE = new Set(['install', 'i', 'in', 'ins', 'inst', 'insta', 'instal', 'isntall', 'add', 'update', 'up', 'upgrade',
  'uninstall', 'un', 'unlink', 'remove', 'rm', 'r', 'ci', 'clean-install', 'install-clean', 'it', 'cit', 'link', 'ln', 'pkg', 'prune', 'dedupe', 'ddp']);
const PM_INSTALLS = new Set(['install', 'i', 'in', 'ins', 'inst', 'insta', 'instal', 'isntall', 'add', 'update', 'up', 'upgrade', 'ci', 'clean-install', 'install-clean', 'it', 'cit']);
const DELETERS = new Set(['rimraf', 'del', 'del-cli', 'trash', 'trash-cli', 'rm']);
const RUNNERS = new Set(['npx', 'pnpx', 'bunx']);
const PM_REMOVE = new Set(['uninstall', 'un', 'unlink', 'remove', 'rm', 'r']);
// Package-manager options that take a value as the next word.
const PM_OPTS_WITH_VALUE = new Set(['--prefix', '-C', '--dir', '--cwd', '--loglevel', '--cache', '--userconfig', '--globalconfig',
  '-w', '--workspace', '--filter', '-F', '--tag', '--registry', '--scope', '--otp', '--before', '--omit', '--include', '--install-strategy']);
// Wrapper commands, and which of their options take a value.
const WRAPPER_OPTS = {
  sudo: new Set(['-u', '-g', '-C', '-h', '-p', '-r', '-t', '-U']),
  doas: new Set(['-u', '-C']),
  command: new Set(),
  builtin: new Set(),
  exec: new Set(['-a']),
  env: new Set(['-u', '-C', '-S', '--unset', '--chdir']),
  time: new Set(['-f', '-o', '--format', '--output']),
  nohup: new Set(),
  nice: new Set(['-n', '--adjustment']),
  ionice: new Set(['-c', '-n', '-p']),
  timeout: new Set(['-s', '-k', '--signal', '--kill-after']),
  stdbuf: new Set(['-i', '-o', '-e']),
  caffeinate: new Set(['-t', '-w']),
  corepack: new Set(),
};
const RUNNER_OPTS_WITH_VALUE = new Set(['-p', '--package', '-c', '--call', '-w', '--workspace']);

function isOpt(t) {
  return typeof t === 'string' && t.startsWith('-') && t !== '-';
}

function namesPiezas(arg) {
  return /^piezas(?:@.*)?$/i.test(arg) || /^npm:piezas(?:@.*)?$/i.test(arg);
}

// pathOperand — an install argument that is a folder, file, tarball, git or
// URL, not a registry package name.
function pathOperand(arg) {
  return /^(?:file|link|workspace|portal|git(?:\+[a-z]+)?|github|gitlab|bitbucket|https?):/i.test(arg) || /^git@/.test(arg) ||
    /^(?:\.\.?(?:\/|$)|\/|~)/.test(arg) || /\.(?:tgz|tar\.gz|tar)$/i.test(arg) || /^[\w.-]+\/[\w.-]+(?:#.*)?$/.test(arg);
}

function declaresPiezas(dir) {
  try {
    const pkg = JSON.parse(readFileSync(join(dir, 'package.json'), 'utf-8'));
    return DEP_FIELDS.some((f) => pkg?.[f] && typeof pkg[f] === 'object' && pkg[f].piezas);
  } catch {
    return false;
  }
}

// The piezas version a lock file would install, or null.
function lockedPiezas(dir) {
  try {
    const lock = JSON.parse(readFileSync(join(dir, 'package-lock.json'), 'utf-8'));
    const v = lock?.packages?.['node_modules/piezas']?.version ?? lock?.dependencies?.piezas?.version;
    return typeof v === 'string' ? v : null;
  } catch {
    return null;
  }
}

function atLeast(version, min) {
  const a = String(version).replace(/^[^\d]*/, '').split(/[.-]/).map((n) => Number.parseInt(n, 10) || 0);
  const b = String(min).split('.').map((n) => Number(n));
  for (let i = 0; i < 3; i += 1) {
    if ((a[i] ?? 0) !== (b[i] ?? 0)) return (a[i] ?? 0) > (b[i] ?? 0);
  }
  return true;
}

// patchTargets — the paths a patch file names (unified diff and git headers).
function patchTargets(text) {
  const out = [];
  for (const m of String(text || '').matchAll(/^(?:\+\+\+|---) (?:[ab]\/)?([^\t\n]+)|^diff --git a\/(\S+) b\/(\S+)|^rename (?:from|to) (.+)$/gm)) {
    for (const p of [m[1], m[2], m[3], m[4]]) if (p && p !== '/dev/null') out.push(p.trim());
  }
  return out;
}

// archiveEntries — what an archive holds (tar -t / unzip -Z1), or null.
function archiveEntries(tool, archive) {
  try {
    const r = tool === 'unzip'
      ? spawnSync('unzip', ['-Z1', archive], { encoding: 'utf-8', timeout: 3000 })
      : spawnSync('tar', ['-tf', archive], { encoding: 'utf-8', timeout: 3000 });
    return r.status === 0 ? String(r.stdout).split('\n').filter(Boolean) : null;
  } catch {
    return null;
  }
}

// shellProblem — what in this shell command touches the guardrails, or null.
// shell is analyzeShell's result for the same command (its targets are
// checked by fileProblem; this adds what a target list cannot show).
export function shellProblem(command, cwd, project, shell, env = process.env) {
  if (!project) return null;
  const installed = hooksInstalled(project);
  const cliThere = existsSync(join(project, 'node_modules', 'piezas'));
  if (!installed && !cliThere) return null;
  const terminal = ' (The owner can run it in their own terminal.)';
  const ctx = { cwd: cwd ? resolve(cwd) : null, env };
  const at = (p) => (p === null || p === undefined ? null : isAbsolute(p) ? resolve(p) : ctx.cwd ? resolve(ctx.cwd, p) : null);
  const touches = (abs) => {
    if (!abs) return true; // unknown: assume it does
    const rel = relKey(abs, project, env);
    if (rel === null) return false;
    // The path itself is protected, inside a protected tree, or holds one.
    const kind = protectedKind(rel);
    if (kind && kind !== 'package' && kind !== 'lock' && kind !== 'npmrc') return true;
    return [...PROTECTED_FILES, ...PROTECTED_TREES].some((p) => p.startsWith(`${rel}/`));
  };
  const inProject = (abs) => !!abs && relKey(abs, project, env) !== null;
  const redirectedIn = (text) => [...String(text).matchAll(/<\s*([^\s<>;|&]+)/g)].map((m) => m[1]);

  // checkWords — one simple command (words as { raw, text }); returns a reason or null.
  const checkWords = (input, depth = 0) => {
    let ws = input;
    // Wrapper commands (and their own options, with the values some take).
    while (ws[0] && (/^[A-Za-z_][A-Za-z0-9_]*=/.test(ws[0].raw) || WRAPPER_OPTS[basename(ws[0].raw)] !== undefined)) {
      const takesValue = WRAPPER_OPTS[basename(ws[0].raw)] ?? new Set();
      const isTimeout = basename(ws[0].raw) === 'timeout';
      ws = ws.slice(1);
      while (ws[0] && isOpt(ws[0].raw)) {
        ws = ws.slice(takesValue.has(ws[0].raw) ? 2 : 1);
      }
      if (isTimeout && ws[0]) ws = ws.slice(1); // its duration
    }
    if (!ws.length || depth > 3) return null;
    const name = basename(ws[0].raw);
    const args = ws.slice(1);
    if (name === 'cd' || name === 'pushd') {
      const t = args.find((a) => !isOpt(a.raw));
      ctx.cwd = t?.text ? at(t.text) : null;
      return null;
    }
    if (name === 'git') {
      let k = 0;
      let gitCwd = ctx.cwd;
      while (k < args.length && isOpt(args[k].raw)) {
        if (args[k].raw === '-C') { gitCwd = at(args[k + 1]?.text); k += 2; continue; }
        if (args[k].raw === '-c') { k += 2; continue; }
        k += 1;
      }
      if (!inProject(gitCwd ?? ctx.cwd) && !installed) return null;
      const sub = args[k]?.raw;
      const rest = args.slice(k + 1);
      const flags = rest.filter((a) => isOpt(a.raw)).map((a) => a.raw);
      const dd = rest.findIndex((a) => a.raw === '--');
      const pathArgs = (dd >= 0 ? rest.slice(dd + 1) : rest.filter((a) => !isOpt(a.raw))).map((a) => (a.text === null ? null : resolve(gitCwd ?? '.', a.text)));
      const existing = dd >= 0 ? pathArgs : pathArgs.filter((p) => p === null || existsSync(p));
      const pathsTouch = (list) => list.some((p) => touches(p));
      const force = flags.some((f) => f === '-f' || f === '--force' || f === '--discard-changes' || /^-[a-zA-Z]*f/.test(f));
      if ((sub === 'checkout' || sub === 'restore') && (pathsTouch(existing) || (sub === 'checkout' && force))) return `\`git ${sub}\` would put back the files that run the Piezas guardrails.${terminal}`;
      if (sub === 'switch' && force) return `\`git switch\` with force would throw away changes to the files that run the Piezas guardrails.${terminal}`;
      if ((sub === 'rm' || sub === 'mv') && pathsTouch(sub === 'mv' ? pathArgs.slice(0, -1) : pathArgs)) return `\`git ${sub}\` would remove the files that run the Piezas guardrails.${terminal}`;
      if (sub === 'read-tree' && flags.some((f) => f === '-u' || f === '--reset' || f === '-m')) return `\`git read-tree\` would rewrite the files that run the Piezas guardrails.${terminal}`;
      if (sub === 'clean' && (flags.some((f) => /^-[a-zA-Z]*[xX]/.test(f)) || !pathArgs.length || pathsTouch(pathArgs))) {
        return `\`git clean\` could delete the files that run the Piezas guardrails.${terminal}`;
      }
      if (sub === 'reset' && flags.some((f) => f === '--hard' || f === '--merge' || f === '--keep')) {
        return `\`git reset ${flags.join(' ')}\` would put back every file, the ones that run the Piezas guardrails included.${terminal}`;
      }
      if (sub === 'stash') {
        const action = rest.find((a) => !isOpt(a.raw))?.raw;
        if (!['list', 'show', 'drop', 'clear'].includes(action)) {
          const specs = dd >= 0 ? pathArgs : [];
          if (!specs.length || pathsTouch(specs)) return `\`git stash\` could change the files that run the Piezas guardrails.${terminal}`;
        }
      }
      if (sub === 'apply' || sub === 'am') {
        if (flags.some((f) => ['--check', '--stat', '--numstat', '--summary'].includes(f))) return null;
        const files = rest.filter((a) => !isOpt(a.raw)).map((a) => at(a.text));
        if (!files.length || files.some((f) => !f || !existsSync(f))) return `\`git ${sub}\` reads a change the guard cannot see in advance.${terminal}`;
        if (files.some((f) => patchTargets(readText(f)).some((p) => touches(resolve(gitCwd ?? ctx.cwd ?? '.', p))))) return `\`git ${sub}\` would change the files that run the Piezas guardrails.${terminal}`;
      }
      return null;
    }
    if (name === 'patch') {
      const ti = args.findIndex((a) => a.raw === '-i' || a.raw === '--input');
      const files = [...(ti >= 0 ? [args[ti + 1]?.text] : []), ...redirectedIn(command)].map((f) => at(f));
      if (!files.length || files.some((f) => !f || !existsSync(f))) return `\`patch\` reads a change the guard cannot see in advance.${terminal}`;
      if (files.some((f) => patchTargets(readText(f)).some((p) => touches(resolve(ctx.cwd ?? '.', p))))) return `\`patch\` would change the files that run the Piezas guardrails.${terminal}`;
      return null;
    }
    if (name === 'tar' || name === 'bsdtar' || name === 'unzip') {
      const texts = args.map((a) => a.raw);
      const extracting = name === 'unzip' ? !texts.some((t) => t === '-l' || t === '-Z' || t === '-Z1' || t === '-t') : texts.some((t) => /^-?[a-zA-Z]*x/.test(t) || t === '--extract' || t === '--get');
      if (!extracting) return null;
      const destFlag = name === 'unzip' ? ['-d'] : ['-C', '--directory'];
      const di = texts.findIndex((t) => destFlag.includes(t));
      const dest = di >= 0 ? at(args[di + 1]?.text) : ctx.cwd;
      if (!inProject(dest)) return null;
      let archive = null;
      if (name === 'unzip') archive = args.find((a, i) => !isOpt(a.raw) && i !== di + 1)?.text ?? null;
      else {
        const fi = texts.findIndex((t) => t === '-f' || t === '--file' || /^-?[a-zA-Z]*f$/.test(t));
        archive = fi >= 0 ? args[fi + 1]?.text ?? null : null;
      }
      const entries = archive ? archiveEntries(name === 'unzip' ? 'unzip' : 'tar', at(archive)) : null;
      if (!entries) return `\`${name}\` would unpack files the guard cannot see in advance into this app.${terminal}`;
      if (entries.some((e) => e.split('/').includes('..') || touches(resolve(dest, e)))) return `\`${name}\` would unpack over the files that run the Piezas guardrails.${terminal}`;
      return null;
    }
    if (PM.has(name) || RUNNERS.has(name)) {
      // Operands, skipping the values of options that take one
      // (npm --prefix . uninstall piezas, pnpm -C . remove piezas).
      const operands = [];
      for (let i = 0; i < args.length; i += 1) {
        const t = args[i].raw;
        if (isOpt(t)) {
          if (PM_OPTS_WITH_VALUE.has(t)) i += 1;
          continue;
        }
        operands.push(args[i]);
      }
      // Whatever the order of words: removing piezas.
      if (PM.has(name) && args.some((a) => PM_REMOVE.has(a.raw)) && args.some((a) => namesPiezas(a.raw))) {
        return `\`${name}\` would remove the piezas tools the Piezas guardrails run from.${terminal}`;
      }
      // A runner: what it runs is checked too (npx pnpm remove piezas,
      // npm exec -- npm uninstall piezas, pnpm dlx rimraf node_modules).
      const runnerSub = !RUNNERS.has(name) && operands[0] && ['exec', 'x', 'dlx'].includes(operands[0].raw);
      if (RUNNERS.has(name) || runnerSub) {
        let list = RUNNERS.has(name) ? args : args.slice(args.indexOf(operands[0]) + 1);
        const dd = list.findIndex((a) => a.raw === '--');
        if (dd >= 0) list = list.slice(dd + 1);
        else {
          const out = [];
          for (let i = 0; i < list.length; i += 1) {
            if (RUNNER_OPTS_WITH_VALUE.has(list[i].raw)) { i += 1; continue; }
            if (isOpt(list[i].raw) && !out.length) continue;
            out.push(list[i]);
          }
          list = out;
        }
        if (!list.length) return null;
        const tool = basename(list[0].raw).replace(/@.*$/, '');
        if (DELETERS.has(tool) && list.slice(1).some((a) => touches(at(a.text)))) {
          return `\`${tool}\` would delete the files that run the Piezas guardrails.${terminal}`;
        }
        if (PM.has(tool) || tool === 'corepack' || DELETERS.has(tool)) return checkWords([{ ...list[0], raw: tool }, ...list.slice(1)], depth + 1);
        return null;
      }
      const sub = operands[0]?.raw ?? (name === 'yarn' ? 'install' : null);
      // Where packages come from: never changed while the guardrails run.
      if ((sub === 'config' || sub === 'set' || sub === 'c') && operands.slice(1).some((a) => /registry|^edit$/i.test(a.raw))) {
        return `\`${name} ${sub}\` would change where packages are installed from, the piezas tools included.${terminal}`;
      }
      if (args.some((a) => /^--(?:registry|@[^=]+:registry)(?:=|$)/.test(a.raw))) {
        return `\`${name}\` with another registry could install other piezas tools than the published ones.${terminal}`;
      }
      if (!sub || !PM_CHANGE.has(sub)) return null;
      const rest = operands.slice(1);
      const named = rest.filter((a) => namesPiezas(a.raw));
      // Adding piezas when the project has none yet, at a version that runs
      // the hooks (0.7.0 or newer): the way back from a missing dependency.
      const addsMissing = named.length > 0 && PM_INSTALLS.has(sub) && !declaresPiezas(project)
        && named.every((a) => { const m = /^piezas@\^?~?(\d+\.\d+\.\d+)$/i.exec(a.raw); return m && atLeast(m[1], '0.7.0'); });
      if ((named.length || args.some((a) => /^--?[a-z-]+=piezas(@|$)/i.test(a.raw))) && !addsMissing) {
        return `\`${name} ${sub}\` would change the piezas tools the Piezas guardrails run from.${terminal}`;
      }
      if (sub === 'link' || sub === 'ln') return `\`${name} link\` would replace installed packages with local copies, the piezas tools included.${terminal}`;
      if (PM_INSTALLS.has(sub) && rest.some((a) => pathOperand(a.raw))) {
        return `\`${name} ${sub}\` from a folder, file or address could replace the piezas tools the guardrails run from.${terminal}`;
      }
      const noDev = args.some((a) => /^--(?:omit(?:=|$)|production(?:=true)?$|only=prod|prod$)/.test(a.raw));
      if (noDev || sub === 'prune') return `\`${name} ${sub}\` without the dev tools would remove the piezas tools the guardrails run from.${terminal}`;
      if (sub === 'pkg' && rest.some((a) => /piezas|devDependencies|overrides|resolutions|dependencies/i.test(a.raw))) {
        return `\`${name} pkg\` would change the piezas tools the Piezas guardrails run from.${terminal}`;
      }
      if (['ci', 'clean-install', 'install-clean', 'it', 'cit'].includes(sub)) {
        const v = lockedPiezas(project);
        if (!v || !atLeast(v, '0.7.0')) return `\`${name} ${sub}\` reinstalls from a lock file without the piezas tools the guardrails need.${terminal}`;
      }
      return null;
    }
    if (DELETERS.has(name) && name !== 'rm') {
      if (args.filter((a) => !isOpt(a.raw)).some((a) => touches(at(a.text)))) return `\`${name}\` would delete the files that run the Piezas guardrails.${terminal}`;
      return null;
    }
    if (name === 'find') {
      const texts = args.map((a) => a.raw);
      const del = texts.includes('-delete') || texts.some((t, i) => (t === '-exec' || t === '-execdir' || t === '-ok') && /^(?:rm|unlink|shred|mv|truncate|cp|tee|sed)$/.test(basename(texts[i + 1] ?? '')));
      if (!del) return null;
      const firstExpr = texts.findIndex((t) => t.startsWith('-') || t === '(' || t === '!');
      const roots = (firstExpr < 0 ? args : args.slice(0, firstExpr)).map((a) => at(a.text));
      if (!roots.length) roots.push(ctx.cwd);
      const patterns = [];
      for (let i = 0; i < texts.length; i += 1) {
        if (['-name', '-iname', '-path', '-ipath', '-wholename', '-regex', '-iregex'].includes(texts[i])) patterns.push(texts[i + 1] ?? '');
      }
      const hitsRoot = roots.some((r) => touches(r) || (r && relKey(r, project, env) !== null && protectedKind(relKey(r, project, env))));
      if (!hitsRoot) return null;
      if (!patterns.length) return `\`find ... -delete\` here would reach the files that run the Piezas guardrails.${terminal}`;
      const matches = patterns.some((p) => {
        const re = globToRegExp(foldPath(basename(p), env));
        return PROTECTED_NAMES.some((n) => re.test(n)) || /piezas|claude|codex|hook|node_modules|settings|config|rules/i.test(p);
      });
      if (matches) return `\`find ... -delete\` would reach the files that run the Piezas guardrails.${terminal}`;
      return null;
    }
    return null;
  };

  for (const { words } of tokenizeShell(command)) {
    const reason = checkWords(words.map((w) => ({ raw: w.text, text: expandWord(w, ctx) })));
    if (reason) return reason;
  }
  // A command that names one of these files and writes somewhere the guard
  // cannot work out ($VAR paths, command output) or runs an inline script
  // that writes: it could be writing them.
  if (installed && MENTIONS.test(command) && (shell?.unknown > 0 || shell?.scripted)) {
    return 'this command names the files that run the Piezas guardrails and writes to a place that cannot be checked in advance';
  }
  return null;
}
